genericcontrol.script:
local _sIcon = "";
function setData(sIcon)
	_sIcon = sIcon;
	setIcon(sIcon);
	setTooltipText(Interface.getString((sIcon:gsub("^kgmi_", "kgmi_name_"))));
end
function getData()
	return _sIcon;
end
function onClickDown()
	return true;
end
function onClickRelease()
	WindowManager.callOuterWindowFunction(window, "handleBundled", _sIcon);
	return true;
end

windowclass.script:
local TILE = 58;
local GAP = 6;
local TOP = 24;
local _tTiles = {};
function onInit()
	for i,sIcon in ipairs(KrakenGMIcon.ICONS) do
		local c = createControl("kgmi_tile", "tile_" .. i);
		c.setStaticBounds(10 + (i - 1) * (TILE + GAP), TOP, TILE, TILE);
		c.setData(sIcon);
		_tTiles[sIcon] = c;
	end
	update();
end
function update()
	local sKind, sName = KrakenGMIcon.parseChoice(KrakenGMIcon.getChoice());
	for sIcon,c in pairs(_tTiles) do
		if sKind == "icon" and sName == sIcon then
			c.setBackColor("70D2B56B");
		else
			c.setBackColor(nil);
		end
	end
	current.setValue(string.format(Interface.getString("kgmi_label_current"), KrakenGMIcon.getChoiceLabel()));
end
